<?php function redirect(string $p):never{header('Location: '.BASE_URL.$p);exit;}function e(?string $s):string{return htmlspecialchars($s??'',ENT_QUOTES,'UTF-8');}function csrf_token():string{if(empty($_SESSION['_csrf']))$_SESSION['_csrf']=bin2hex(random_bytes(32));return $_SESSION['_csrf'];}function csrf_field():string{return '<input type="hidden" name="_csrf" value="'.e(csrf_token()).'">';}function verify_csrf():void{if(!hash_equals($_SESSION['_csrf']??'',$_POST['_csrf']??'')){http_response_code(419);exit('Token tidak valid');}}